/**
 * Bundles migrations/*.sql into src/worker/db/migrations.gen.ts so the Worker
 * can apply its own schema at runtime (see src/worker/db/bootstrap.ts). Runs as
 * part of `npm run db:generate` — commit the generated file.
 *
 * Why not import the .sql files directly? Runtime self-migration is what makes
 * "deploy and it just works" true (no wrangler CLI step), and a generated .ts
 * file works in every toolchain (vite, vitest, wrangler) without ?raw loaders.
 */
import { readdir, readFile, writeFile } from "node:fs/promises";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const migrationsDir = join(root, "migrations");
const outFile = join(root, "src/worker/db/migrations.gen.ts");

const files = (await readdir(migrationsDir))
	.filter((f) => f.endsWith(".sql"))
	.sort();

const entries = [];
for (const file of files) {
	const sql = await readFile(join(migrationsDir, file), "utf8");
	entries.push({ version: file.replace(/\.sql$/, ""), sql });
}

const body = `// AUTO-GENERATED by scripts/bundle-migrations.mjs — do not edit.
// Regenerate with: npm run db:generate

export interface Migration {
	version: string;
	sql: string;
}

export const MIGRATIONS: Migration[] = ${JSON.stringify(entries, null, "\t")};
`;

await writeFile(outFile, body);
console.log(`Bundled ${entries.length} migration(s) into src/worker/db/migrations.gen.ts`);
